/// <summary>
/// class METGeneratePriceChangeInquiryBasePriceDialog
/// </summary>
internal final class METGeneratePriceChangeInquiryBasePriceDialog extends RunBaseBatch implements BatchRetryable
{
    internal METPriceChangeInquiryActivationDate    activationDate;
    internal METPriceChangeInquiryInterval          interval;
    internal METPriceChangeInquiryItemNumber        itemId;
    internal METPriceChangeInquirySite              siteId;
    internal GUPPriceReportName                     reportName;
    internal guid                                   sessionGuid;

    protected QueryRun      queryRun;

    #DEFINE.CURRENTVERSION(1)
    #LOCALMACRO.CurrentList
        reportName,
        activationDate,
        interval,
        itemId,
        siteId
    #Endmacro

}

Method.Source:
    /// <summary>
    /// Initialize 
    /// </summary>
    /// <returns>boolean value</returns>
    public boolean init()
    {
        boolean ret = super();

        itemId = '';
        siteId = '';
        interval = 1;

        return ret;
    }

/// <summary>
/// retryable
/// </summary>
/// <returns>boolean value</returns>
[Hookable(false)]
final boolean isRetryable()
{
    return true;
}

/// <summary>
/// Construct the class
/// </summary>
/// <returns>METGeneratePriceChangeInquiryBasePriceDialog</returns>
static METGeneratePriceChangeInquiryBasePriceDialog construct()
{
    return new METGeneratePriceChangeInquiryBasePriceDialog();
}

    /// <summary>
    /// new method
    /// </summary>
    public void new()
    {
        this.initSessionGuid();

        super();
    }

    /// <summary>
    /// main method
    /// </summary>
    /// <param name = "_args">args</param>
    public static void main(Args _args)
    {
        METGeneratePriceChangeInquiryBasePriceDialog priceChangeInquiryDialog = METGeneratePriceChangeInquiryBasePriceDialog::construct();

        if (priceChangeInquiryDialog.prompt())
        {
            priceChangeInquiryDialog.runOperation();
        }
    }

    /// <summary>
    /// get from dialog
    /// </summary>
    /// <returns>boolean value</returns>
    public boolean getFromDialog()
    {
        this.initQueryRun();

        return super();
    }

/// <summary>
/// init query run
/// </summary>
internal void initQueryRun()
{
    queryRun = new QueryRun(this.initQuery());
}

    /// <summary>
    /// init query
    /// </summary>
    /// <returns>Query</returns>
    private Query initQuery()
    {
        ListIterator        iterator;
        GUPParameters       parameters = GUPParameters::find();

        Query query = new Query();
        QueryBuildDataSource qbdsRoot = query.addDataSource(tableNum(GUPItemBasePrice));
        qbdsRoot.addRange(fieldNum(GUPItemBasePrice, PriceType)).value(SysQuery::value(parameters.ActivePrice_FallbackPriceBasis));
        qbdsRoot.addRange(fieldNum(GUPItemBasePrice, Calculated)).value(SysQuery::value(NoYes::Yes));
        qbdsRoot.addRange(fieldNum(GUPItemBasePrice, ActivationDate)).value(SysQuery::value(activationDate));
        qbdsRoot.addRange(fieldNum(GUPItemBasePrice, FromDate)).value(SysQuery::range(activationDate, dateMax()));

        if (this.parmItemId())
        {
            iterator = new ListIterator(strSplit(this.parmItemId(), ','));
            while (iterator.more())
            {
                qbdsRoot.addRange(fieldNum(GUPItemBasePrice, ItemId)).value(SysQuery::value(iterator.value()));
                iterator.next();
            }
        }

        QueryBuildDataSource qbdsInventDim = qbdsRoot.addDataSource(tableNum(InventDim));
        qbdsInventDim.addLink(fieldNum(GUPItemBasePrice, inventDimId), fieldNum(InventDim, inventDimId));
        qbdsInventDim.joinMode(JoinMode::InnerJoin);
        qbdsInventDim.fetchMode(QueryFetchMode::One2One);

        iterator = new ListIterator(strSplit(this.parmSiteId(), ','));
        while (iterator.more())
        {
            qbdsInventDim.addRange(fieldNum(InventDim, InventSiteId)).value(SysQuery::value(iterator.value()));
            iterator.next();
        }

        QueryBuildDataSource qbdsPriceCalcTable = qbdsRoot.addDataSource(tableNum(GUPItemBasePriceCalcTable));
        qbdsPriceCalcTable.addLink(fieldNum(GUPItemBasePrice, PriceCalcId), fieldNum(GUPItemBasePriceCalcTable, PriceCalcId));
        qbdsPriceCalcTable.joinMode(JoinMode::InnerJoin);
        qbdsPriceCalcTable.fetchMode(QueryFetchMode::One2One);

        return query;
    }

/// <summary>
/// dialog
/// </summary>
/// <returns>object</returns>
public Object dialog()
{
    return this.dialogInternal(Dialog::newFormnameRunbase(formstr(METPriceChangeInquiryBasePriceDialog), this));
}

/// <summary>
/// pack
/// </summary>
/// <returns>container value</returns>
public container pack()
{
    return [#CurrentVersion, #CurrentList];
}

/// <summary>
/// init session guid
/// </summary>
private void initSessionGuid()
{
    sessionGuid = newGuid();
}

    /// <summary>
    /// sessionGuid
    /// </summary>
    /// <param name = "_sessionGuid">_sessionGuid</param>
    /// <returns>SysGuid</returns>
