    public GUPPriceReportName parmReportName(GUPPriceReportName _reportName = reportName)
    {
        reportName = _reportName;

        return reportName;
    }

    /// <summary>
    /// Activation date
    /// </summary>
    /// <param name = "_date">date</param>
    /// <returns>activationDate</returns>
    public METPriceChangeInquiryActivationDate parmActivationDate(METPriceChangeInquiryActivationDate _date = activationDate)
    {
        activationDate = _date;

        return activationDate;
    }

    /// <summary>
    /// Interval
    /// </summary>
    /// <param name = "_interval">interval</param>
    /// <returns>interval</returns>
    public METPriceChangeInquiryInterval parmInterval(METPriceChangeInquiryInterval _interval = interval)
    {
        interval = _interval;

        return interval;
    }

    /// <summary>
