        itemId = _itemId;

        return itemId;
    }

    /// <summary>
    /// SiteId
    /// </summary>
    /// <param name = "_siteId">SiteId</param>
    /// <returns>SiteId</returns>
    public METPriceChangeInquirySite parmSiteId(METPriceChangeInquirySite _siteId = siteId)
