    }

    /// <summary>
    /// unpack
    /// </summary>
    /// <param name = "packedClass">packedClass</param>
    /// <returns>boolean value</returns>
    boolean unpack(container packedClass)
    {
        Integer     version     = conPeek(packedClass, 1);

        switch (version)
        {
            case #CurrentVersion :
                [version, #CurrentList] = packedClass;

                break;
            default :
                return false;
        }

        return true;
    }

    /// <summary>
    /// get last
    /// </summary>
    public final void getLast()
    {
        super();

        this.init();
    }

/// <summary>
/// Session
/// </summary>
/// <returns>boolean value</returns>
protected boolean canRunInNewSession()
{
    return false;
}

/// <summary>
/// Description
/// </summary>
/// <returns>Description</returns>
public static ClassDescription description()
{
    return "@GlobalUnifiedPricingMetcash:METGeneratePriceChangeInquiryBasePriceDialog";
}

    /// <summary>
    /// validate
    /// </summary>
    /// <param name = "_calledFrom">calledFrom</param>
    /// <returns>boolean value</returns>
    public boolean validate(Object _calledFrom = null)
    {
        boolean ret = super(_calledFrom);

        ret = ret && this.parmSiteId() && this.parmActivationDate() && this.parmInterval();

        return ret;
    }

    /// <summary>
    /// run 
    /// </summary>
    public void run()
    {
        if (this.parmInBatch())
        {
            this.parmActivationDate(GUPBasePriceVersion::findLatest().LastActivation);
            this.initQueryRun();
        }

        this.generatePriceChangeInquriy();

        this.comparePriceDifferenceAndPopulateData();
    }

    /// <summary>
    /// GeneratePriceChangeInquriy
    /// </summary>
    private void generatePriceChangeInquriy()
    {
        METPriceChangeInquiry priceChangeInquiry;
        date today = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());

        ttsbegin;

        priceChangeInquiry.ReportName               = this.parmReportName();
        priceChangeInquiry.GeneratedDate            = today;
        priceChangeInquiry.GeneratedBy              = curUserId();
        priceChangeInquiry.RetentionExpirationDate  = nextQtr(today);
        priceChangeInquiry.ReportId                 = this.parmSessionGuid();
        priceChangeInquiry.ItemId                   = this.parmItemId();
        priceChangeInquiry.Site                     = this.parmSiteId();
        priceChangeInquiry.ActivationDate           = this.parmActivationDate();
        priceChangeInquiry.Interval                 = this.parmInterval();

        priceChangeInquiry.insert();

        ttscommit;
    }

    /// <summary>
    /// GeneratePriceChangeInquriyLine
    /// </summary>
    /// <param name = "_itemId">itemId</param>
    /// <param name = "_inventSiteId">inventSiteId</param>
    /// <param name = "_previoudPrice">previoudPrice</param>
    /// <param name = "_toDate">toDate</param>
    /// <param name = "_currentPrice">currentPrice</param>
    /// <param name = "_fromDate">fromDate</param>
    /// <param name = "_currency">currency</param>
    /// <param name = "_AccountRelation">AccountRelation</param>
    /// <param name = "_offerId">offerId</param>
    /// <returns>METPriceChangeInquiryLineTmp</returns>
    private METPriceChangeInquiryLineTmp generatePriceChangeInquriyLine(
        ItemId                          _itemId,
        InventSiteId                    _inventSiteId,
        real                            _previoudPrice,
        ToDate                          _toDate,
        real                            _currentPrice,
        FromDate                        _fromDate,
        CurrencyCode                    _currency,
        GUPVendPriceRelation            _AccountRelation,
        RetailPeriodicDiscountOfferId   _offerId)
    {
        METPriceChangeInquiryLineTmp priceChangeInquiryLineTmp;

        priceChangeInquiryLineTmp.ReportId         = this.parmSessionGuid();
        priceChangeInquiryLineTmp.ItemId           = _itemId;
        priceChangeInquiryLineTmp.InventSiteId     = _inventSiteId;
        priceChangeInquiryLineTmp.PreviousPrice    = _previoudPrice;
        priceChangeInquiryLineTmp.ToDate           = _toDate;
        priceChangeInquiryLineTmp.CurrentPrice     = _currentPrice;
        priceChangeInquiryLineTmp.FromDate         = _fromDate;
        priceChangeInquiryLineTmp.Currency         = _currency;
        priceChangeInquiryLineTmp.OfferId          = _offerId;
        priceChangeInquiryLineTmp.AccountRelation  = _AccountRelation;

        priceChangeInquiryLineTmp.Variance         = _currentPrice - _previoudPrice;
        priceChangeInquiryLineTmp.SHA1HashHex      = priceChangeInquiryLineTmp.hashValue();

        return priceChangeInquiryLineTmp;
    }

    /// <summary>
    /// comparePriceDifferenceAndPopulateData
    /// </summary>
    private void comparePriceDifferenceAndPopulateData()
    {
        GUPItemBasePrice                futurePrice;
        InventDim                       inventDim;
        GUPItemBasePriceCalcTable       basePriceCalcTable;
        METPriceChangeInquiryLine       priceChangeInquiryLine;
        METPriceChangeInquiryLineTmp    priceChangeInquiryLineTmp;

        while (queryRun.next())
        {
            futurePrice = queryRun.get(tableNum(GUPItemBasePrice));
            inventDim = queryRun.get(tableNum(InventDim));
            basePriceCalcTable = queryRun.get(tableNum(GUPItemBasePriceCalcTable));

            GUPItemBasePrice currentPrice = this.findCurrentPrice(futurePrice, basePriceCalcTable.Currency);

            if (currentPrice.RecId)
            {
                List offerIds = this.findImpactedDiscounts(futurePrice, basePriceCalcTable.Currency);
                ListIterator iterator = new ListIterator(offerIds);

                while (iterator.more())
                {
                    priceChangeInquiryLineTmp = this.generatePriceChangeInquriyLine(futurePrice.ItemId,
                                                                                    InventDim.InventSiteId,
                                                                                    currentPrice.Price,
                                                                                    currentPrice.ToDate,
                                                                                    futurePrice.Price,
                                                                                    futurePrice.FromDate,
                                                                                    basePriceCalcTable.Currency,
                                                                                    futurePrice.AccountRelation,
                                                                                    iterator.value());

                    priceChangeInquiryLineTmp.insert();

                    iterator.next();
                }
            }
        }

        insert_recordset priceChangeInquiryLine
            (ReportId,
            ItemId,
            InventSiteId,
            PreviousPrice,
            ToDate,
            CurrentPrice,
            FromDate,
            Currency,
            OfferId,
            AccountRelation,
            Variance,
            SHA1HashHex)
         select
            ReportId,
            ItemId,
            InventSiteId,
            PreviousPrice,
            ToDate,
            CurrentPrice,
            FromDate,
            Currency,
            OfferId,
            AccountRelation,
            Variance,
            SHA1HashHex
        from priceChangeInquiryLineTmp
            notexists join priceChangeInquiryLine
            where priceChangeInquiryLine.SHA1HashHex == priceChangeInquiryLineTmp.SHA1HashHex;

    }

    /// <summary>
    /// Find the current price
    /// </summary>
    /// <param name = "_futurePrice">futurePrice</param>
    /// <param name = "_currency">currency</param>
    /// <returns>GUPItemBasePrice</returns>
    private GUPItemBasePrice findCurrentPrice(GUPItemBasePrice _futurePrice, CurrencyCode _currency)
    {
        GUPItemBasePrice            currentPrice;
        GUPItemBasePriceCalcTable   basePriceCalcTable;

        select firstonly Price, ToDate from currentPrice
            where currentPrice.ItemId == _futurePrice.ItemId
                && currentPrice.InventDimId == _futurePrice.inventDimId
                && currentPrice.UnitId == _futurePrice.UnitId
                && currentPrice.AccountRelation == _futurePrice.AccountRelation
                && currentPrice.ToDate == _futurePrice.FromDate - interval
            exists join basePriceCalcTable
                where basePriceCalcTable.PriceCalcId == currentPrice.PriceCalcId
                    && basePriceCalcTable.Currency == _currency;

        return currentPrice;
    }

    /// <summary>
    /// Find Impacted Discounts
    /// </summary>
    /// <param name = "_futurePrice">futurePrice</param>
    /// <param name = "_currency">currency</param>
    /// <returns>List</returns>
    private List findImpactedDiscounts(GUPItemBasePrice _futurePrice, CurrencyCode _currency)
    {
        List impactedDiscounts = new List(Types::String);

        RetailPeriodicDiscount      discount;
        RetailPeriodicDiscountLine  discountLine;
        GUPPriceComponentCode       componentCode;
        InventDim                   inventDim;
        InventSiteId                inventSiteId    = InventDim::find(_futurePrice.InventDimId).InventSiteId;
        boolean                     matched         = false;

        while select OfferId, IsDiscountCodeRequired from discount
            where discount.IsGUPDiscount == NoYes::Yes
                && ((discount.ValidTo >= _futurePrice.FromDate
                    && (discount.ValidFrom <= _futurePrice.ToDate || _futurePrice.ToDate == dateNull()))
                    || discount.IsDiscountCodeRequired == NoYes::Yes)
                && discount.CurrencyCode == _currency
                && discount.PeriodicDiscountType != RetailDiscountOfferTypeBase::Promotion
                && discount.Status == RetailDisabledEnabled::Enabled
            exists join componentCode
                where discount.PriceComponentCodeName == componentCode.Name
                    && componentCode.METOnHold == NoYes::Yes
        {
            if (discount.IsDiscountCodeRequired)
            {
                RetailCoupon            coupon;
                RetailCouponCodeTable   couponCodeTable;

                select firstonly RecId from coupon
                    where coupon.DiscountOfferId == discount.OfferId
                    exists join couponCodeTable
                        where couponCodeTable.CouponNumber == coupon.CouponNumber
                            && couponCodeTable.ValidTo >= _futurePrice.FromDate
                            && (couponCodeTable.ValidFrom <= _futurePrice.ToDate || _futurePrice.ToDate == dateNull())
                            && couponCodeTable.Status == RetailCouponStatus::Active;

                if (!coupon.RecId)
                {
                    continue;
                }
            }

            while select LinePricingRule, LinePricingGroupCode from discountLine
                where discountLine.OfferId == discount.OfferId
                exists join inventDim
                    where discountLine.InventDimId == inventDim.inventDimId
                        && (inventDim.InventSiteId == ''
                            || inventDim.InventSiteId == inventSiteId)
            {
                GUPPricingRuleCopy      pricingRuleCopy;
                InventTable             item;
                QueryRun                qr;

                if (discountLine.LinePricingGroupCode == GUPGroupAll::All)
                {
                    matched = true;
                    impactedDiscounts.addEnd(discount.OfferId);
                }
                else
                {
                    pricingRuleCopy.initFromPricingRule(GUPPricingRule::find(discountLine.LinePricingRule));
                    qr = new QueryRun(GUPPricingObjectQueryBuilder::constructFromPricingRuleCopy(pricingRuleCopy).build());

                    while (qr.next())
                    {
                        item = qr.get(tableNum(InventTable));
                        if (item.ItemId == _futurePrice.ItemId)
                        {
                            matched = true;
                            impactedDiscounts.addEnd(discount.OfferId);

                            break;
                        }
                    }
                }

                if (matched)
                {
                    break;
                }
            }
        }

        return impactedDiscounts;

    }
